responseFormat.typescriptTypesReference:
type Citation = {
commentId: number;
};

type Clause = {
text: string;
citations: Citation[];
};

type Sentence = {
clauses: Clause[];
};

type Paragraph = {
id: string;
title: string;
sentences: Sentence[];
};

type Subtask = {
id: string;
title: string;
paragraphs: Paragraph[];
};

polisAnalysisPrompt.example:
{
"id": "tribe_consensus",
"title": "Tribe Consensus",
"paragraphs": [
{
"id": "tribe_strong_agreement",
"title": "What This Tribe Agrees On",
"sentences": [
{
"clauses": [
{
"text": "This tribe shows strong consensus around the need for transparent governance and clear accountability mechanisms.",
"citations": [101, 115, 204]
},
{
"text": "They also consistently support positions emphasizing community-driven decision-making over top-down approaches.",
"citations": [132, 187, 233]
}
]
}
]
},
{
"id": "tribe_strong_disagreement",
"title": "What This Tribe Disagrees With",
"sentences": [
{
"clauses": [
{
"text": "The tribe notably rejects proposals that would centralize authority without oversight, suggesting a deep commitment to distributed power structures.",
"citations": [221, 245]
},
{
"text": "They also push back against purely aspirational framing, preferring concrete and enforceable commitments.",
"citations": [198, 260]
}
]
}
]
}
]
}
